const AfricasTalking = require('africastalking');

class AfricasTalkingService {
  constructor(credentials) {
    this.client = AfricasTalking({
      apiKey: credentials.apiKey,
      username: credentials.username
    });
    this.sms = this.client.SMS;
    this.voice = this.client.VOICE || this.client.voice || null;
  }

  // ============================================================
  // SMS - UNCHANGED
  // ============================================================
  async sendSMS(phoneNumber, message, shortCode = null) {
    try {
      const options = {
        to: [phoneNumber],
        message: message,
        from: shortCode || ''
      };

      const response = await this.sms.send(options);
      const result = response.SMSMessageData.Recipients[0];

      // todo: Check if returning an error in case of a api failure is better and implement it.
      return {
        success: result.status === 'Success',
        linkId: result.linkId,
        id: result.messageId,
        statusCode: result.statusCode,
        status: result.status,
        cost: result.messageCost,
        error: result.status !== 'Success' ? result.status : null
      };
    } catch (error) {
      return {
        success: false,
        error: error.message
      };
    }
  }

  // ============================================================
  // VOICE / IVR
  // ============================================================

  /**
   * Originates an OUTBOUND call via Africa's Talking Voice API.
   *
   * IMPORTANT: this only *starts* the call. Africa's Talking does not let you
   * "push" audio/TTS into an active call via a separate API request. Instead,
   * once the call is answered (or as soon as an inbound call arrives), AT
   * makes an HTTP POST to your configured Voice callback URL and waits
   * (synchronously) for you to respond with Voice XML describing what to do
   * next (Say / Play / GetDigits / Hangup). See buildVoiceXML() below - that
   * XML is what actually "sends the message" to the caller.
   *
   * @param {string} callFrom - Your registered Africa's Talking Voice number/callerId (E.164)
   * @param {string} callTo - The recipient's phone number (E.164)
   */
  async makeCall(callFrom, callTo) {
    try {
      if (!this.voice || typeof this.voice.call !== 'function') {
        return { success: false, error: "Africa's Talking voice client is unavailable" };
      }

      const response = await this.voice.call({ callFrom, callTo: [callTo] });

      // Typical AT response shape:
      // { errorMessage: 'None', entries: [{ phoneNumber, status: 'Queued', sessionId }] }
      const entry = (response && response.entries && response.entries[0]) || {};
      const status = entry.status || response?.errorMessage || 'Unknown';
      const ok = status === 'Queued' || status === 'Success';

      return {
        success: ok,
        sessionId: entry.sessionId || null,
        status,
        error: ok ? null : status,
        raw: response
      };
    } catch (error) {
      return {
        success: false,
        error: error.message
      };
    }
  }

  /**
   * Builds Africa's Talking "Voice Actions" XML. This is what you respond
   * with, synchronously, to AT's voice callback POST.
   *
   * @param {Object} opts
   * @param {string} [opts.sayText] - Text to read out via Text-To-Speech
   * @param {string} [opts.audioUrl] - URL of an audio file to play (takes priority over sayText)
   * @param {string} [opts.voice] - TTS voice: "man" | "woman" (default "woman")
   * @param {Object} [opts.getDigits] - { numDigits, timeout, finishOnKey } - if provided, the
   *   prompt is wrapped in <GetDigits>, which tells Africa's Talking to collect the caller's key
   *   presses and POST back to this same webhook with `dtmfDigits` once done.
   * @param {boolean} [opts.hangup] - Append a <Hangup/> after the prompt
   * @returns {string} XML string, ready to send with Content-Type: text/xml
   */
  buildVoiceXML(opts = {}) {
    const { sayText, audioUrl, voice = 'woman', getDigits, hangup } = opts;

    const escapeXml = (str) => String(str || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');

    let prompt = '';
    if (audioUrl) {
      prompt += `<Play url="${escapeXml(audioUrl)}"/>`;
    } else if (sayText) {
      prompt += `<Say voice="${escapeXml(voice)}">${escapeXml(sayText)}</Say>`;
    }

    let body = prompt;

    if (getDigits) {
      const numDigitsAttr = getDigits.numDigits ? ` numDigits="${getDigits.numDigits}"` : '';
      const timeoutAttr = getDigits.timeout ? ` timeout="${getDigits.timeout}"` : '';
      const finishOnKeyAttr = getDigits.finishOnKey ? ` finishOnKey="${escapeXml(getDigits.finishOnKey)}"` : '';
      body = `<GetDigits${numDigitsAttr}${timeoutAttr}${finishOnKeyAttr}>${prompt}</GetDigits>`;
    }

    if (hangup) {
      body += '<Hangup/>';
    }

    return `<?xml version="1.0" encoding="UTF-8"?><Response>${body}</Response>`;
  }
}

module.exports = AfricasTalkingService;